// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import java.io.IOException;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

import org.eclipse.rdf4j.sail.lmdb.LmdbAdjacencyMemoryAccount.MemoryKind;

/**
 * Single-thread reference base builder (plan 27, Milestone 4A): the deterministic byte-format oracle and bounded-memory
 * reference path. It consumes the four ordered logical streams of one pinned snapshot through
 * {@link AdjacencySourceScanner}, writes no files, and performs no external sort.
 * <ul>
 * <li>Pass 0 collects the covered predicate dictionary and the base context domain.</li>
 * <li>Pass 1 streams every group through the exact run-codec sizer, counts each node's four plane groups in temporary
 * off-heap count pages, tracks per-type active payload maxima, and sizes the inline incoming planes.</li>
 * <li>The memory gate reserves the complete predicted base output before any base allocation; refusal aborts with the
 * active index unchanged (invariant I8/I17).</li>
 * <li>Pass 2 writes the dictionaries and allocates locator pages and node headers with exact counts.</li>
 * <li>Pass 3 rescans, encodes every run, and fills header entries and inline plane indexes.</li>
 * </ul>
 * Snapshot validity is checked at pass boundaries and periodically inside scans; any invalidation aborts the
 * unpublished build (invariant I15).
 */
final class LmdbAdjacencyBaseBuilder {

	private static final int SNAPSHOT_CHECK_GROUP_INTERVAL = 65_536;

	private LmdbAdjacencyBaseBuilder() {
	}

	static LmdbInMemoryAdjacencyIndex build(AdjacencySourceScanner scanner, LmdbAdjacencyCoverage coverage,
			LmdbAdjacencyMemoryAccount account, long baseArenaRegionBytes, long workspaceRegionBytes)
			throws IOException {
		if (!scanner.supportsOrderedScan(true) || !scanner.supportsOrderedScan(false)) {
			throw new IllegalStateException(
					"NOT_BUILDABLE_WITH_INDEX_CONFIG: a required direction cannot stream its grouping order");
		}
		long baseRevision = scanner.snapshotRevision();

		// ---------------- Pass 0: predicate dictionary and context domain ----------------
		LongList predicateIds = new LongList();
		scanner.scanPredicates(rawId -> {
			if (coverage.covers(rawId)) {
				if (predicateIds.size > 0
						&& Long.compareUnsigned(predicateIds.get(predicateIds.size - 1), rawId) >= 0) {
					throw new IllegalStateException("predicate scan must be strictly unsigned ascending");
				}
				predicateIds.add(rawId);
			}
		});
		LongList contextIds = new LongList();
		scanner.scanContexts(rawId -> {
			if (rawId == 0) {
				return;
			}
			if (contextIds.size > 0 && Long.compareUnsigned(contextIds.get(contextIds.size - 1), rawId) >= 0) {
				throw new IllegalStateException("context scan must be strictly unsigned ascending");
			}
			contextIds.add(rawId);
		});
		scanner.ensureSnapshotValid();

		long[] sortedPredicates = predicateIds.toArray();
		long[] sortedContexts = contextIds.toArray();
		int predicateWidth = LmdbReferenceNodeLocator.predicateWidthForCount(sortedPredicates.length);
		TempContextCatalog tempContexts = new TempContextCatalog(sortedContexts);

		// ---------------- Pass 1: exact sizing and node counts ----------------
		LmdbAdjacencyBuildWorkspace workspace = new LmdbAdjacencyBuildWorkspace(account, lazyHighWater(),
				workspaceRegionBytes);

		SizingState sizing = new SizingState(coverage, tempContexts, sortedPredicates, workspace, scanner);
		boolean success = false;
		LmdbAdjacencyArena baseArena = null;
		try {
			sizing.scanAll();
			scanner.ensureSnapshotValid();

			// ---------------- memory gate: reserve the predicted base output ----------------
			long predictedBytes = sizing.predictedBaseBytes(sortedPredicates.length, sortedContexts.length,
					predicateWidth);
			// growth-mode arenas materialize whole regions; charge the physical capacity, not the logical bytes
			if (predictedBytes > 0) {
				predictedBytes = Math.multiplyExact(
						(predictedBytes + baseArenaRegionBytes - 1) / baseArenaRegionBytes, baseArenaRegionBytes);
			}
			if (!account.tryReserve(MemoryKind.BUILD_OUTPUT, predictedBytes)) {
				throw new LmdbAdjacencyMemoryRefusedException(
						"base output reservation of " + predictedBytes + " bytes refused");
			}
			long reservedBytes = predictedBytes;
			try {
				baseArena = new LmdbAdjacencyArena(baseArenaRegionBytes);

				// ---------------- Pass 2: dictionaries, locator pages, headers ----------------
				LmdbAdjacencyPredicateCatalog predicateCatalog = LmdbAdjacencyPredicateCatalog.base(baseArena,
						sortedPredicates);
				LmdbAdjacencyContextCatalog contextCatalog = LmdbAdjacencyContextCatalog.base(baseArena,
						sortedContexts);
				long[] maxPayloadByType = new long[4];
				for (int t = 0; t < 4; t++) {
					maxPayloadByType[t] = sizing.workspace.maxActivePayloadExclusive(ValueIds.T_URI + t);
				}
				LmdbReferenceNodeLocator.TwoPhaseBuilder twoPhase = LmdbReferenceNodeLocator
						.twoPhaseBuilder(baseArena, predicateWidth, maxPayloadByType);
				sizing.workspace.forEachActiveNode((type, payload, planeCounts) -> twoPhase.declareNode(type, payload,
						planeCounts));
				LmdbReferenceNodeLocator locator = twoPhase.finishAllocation();
				scanner.ensureSnapshotValid();

				// ---------------- Pass 3: encode runs and fill entries ----------------
				FillState fill = new FillState(coverage, contextCatalog, predicateCatalog, baseArena, twoPhase,
						scanner);
				fill.scanAll();
				scanner.ensureSnapshotValid();

				// ---------------- validation ----------------
				if (fill.groupCount != sizing.groupCount || fill.pairCount != sizing.pairCount) {
					throw new IllegalStateException("Pass 3 totals (" + fill.groupCount + " groups, " + fill.pairCount
							+ " pairs) differ from Pass 1 (" + sizing.groupCount + ", " + sizing.pairCount + ")");
				}
				if (fill.runBytes != sizing.runBytes) {
					throw new IllegalStateException("Pass 3 encoded " + fill.runBytes
							+ " run bytes but Pass 1 predicted " + sizing.runBytes);
				}
				if (sizing.outgoingExplicitPairs != sizing.incomingExplicitPairs
						|| sizing.outgoingInferredPairs != sizing.incomingInferredPairs) {
					throw new IllegalStateException("outgoing/incoming statement totals disagree");
				}
				sizing.workspace
						.forEachActiveNode((type, payload, planeCounts) -> twoPhase.verifyFilled(type, payload));
				for (long rawContext : sortedContexts) {
					long ordinal = contextCatalog.ordinalForRaw(rawContext);
					if (ordinal <= 0 || contextCatalog.rawForOrdinal(ordinal) != rawContext) {
						throw new IllegalStateException("context does not round-trip: " + rawContext);
					}
				}

				// reconcile the reservation with the actual native capacity
				long actualBytes = baseArena.capacityBytes();
				if (actualBytes > reservedBytes) {
					if (!account.tryReserve(MemoryKind.BUILD_OUTPUT, actualBytes - reservedBytes)) {
						throw new LmdbAdjacencyMemoryRefusedException(
								"base output exceeded its reservation by " + (actualBytes - reservedBytes) + " bytes");
					}
				} else if (actualBytes < reservedBytes) {
					account.release(MemoryKind.BUILD_OUTPUT, reservedBytes - actualBytes);
				}
				reservedBytes = actualBytes;
				account.reclassify(MemoryKind.BUILD_OUTPUT, MemoryKind.BASE, reservedBytes);

				LmdbAdjacencyArenaCatalog arenaCatalog = LmdbAdjacencyArenaCatalog.of(baseArena);
				long statements = sizing.outgoingExplicitPairs + sizing.outgoingInferredPairs;
				LmdbInMemoryAdjacencyIndex index = new LmdbInMemoryAdjacencyIndex(baseRevision, arenaCatalog,
						predicateCatalog, contextCatalog, coverage, locator, fill.inlinePlanes, account, reservedBytes,
						statements, sizing.pairCount);
				// the catalog is now the sole owner: release the builder's creator reference
				baseArena.close();
				success = true;
				return index;
			} catch (RuntimeException | IOException e) {
				account.release(MemoryKind.BUILD_OUTPUT, reservedBytes);
				throw e;
			}
		} finally {
			if (!success && baseArena != null) {
				baseArena.close();
			}
			sizing.workspace.close();
		}
	}

	private static long[] lazyHighWater() {
		// the reference path has no ValueStore high-water yet: allow a generous payload space per type; count pages
		// are allocated only for touched pages, so this bounds nothing but the Java page-reference directory
		long pages = 1L << 16; // 65,536 pages of 4,096 slots each per type
		long payloads = pages << LmdbReferenceNodeLocator.PAGE_SHIFT;
		return new long[] { payloads, payloads, payloads, payloads };
	}

	// ------------------------------------------------------------------
	// Pass 1
	// ------------------------------------------------------------------

	private static final class SizingState {
		final LmdbAdjacencyCoverage coverage;
		final TempContextCatalog tempContexts;
		final long[] sortedPredicates;
		final LmdbAdjacencyBuildWorkspace workspace;
		final AdjacencySourceScanner scanner;

		long runBytes;
		long groupCount;
		long pairCount;
		long outgoingExplicitPairs;
		long incomingExplicitPairs;
		long outgoingInferredPairs;
		long incomingInferredPairs;
		final Map<Long, InlinePlaneSizing> inlineSizing = new HashMap<>();

		SizingState(LmdbAdjacencyCoverage coverage, TempContextCatalog tempContexts, long[] sortedPredicates,
				LmdbAdjacencyBuildWorkspace workspace, AdjacencySourceScanner scanner) {
			this.coverage = coverage;
			this.tempContexts = tempContexts;
			this.sortedPredicates = sortedPredicates;
			this.workspace = workspace;
			this.scanner = scanner;
		}

		void scanAll() throws IOException {
			scanner.scanOutgoing(true, consumer(LmdbReferenceNodeLocator.PLANE_OUTGOING_EXPLICIT));
			scanner.scanIncoming(true, consumer(LmdbReferenceNodeLocator.PLANE_INCOMING_EXPLICIT));
			scanner.scanOutgoing(false, consumer(LmdbReferenceNodeLocator.PLANE_OUTGOING_INFERRED));
			scanner.scanIncoming(false, consumer(LmdbReferenceNodeLocator.PLANE_INCOMING_INFERRED));
		}

		private AdjacencySourceScanner.GroupConsumer consumer(int plane) {
			return new AdjacencySourceScanner.GroupConsumer() {
				private LmdbAdjacencyRunCodec.Encoder encoder;
				private long key;
				private long predicate;
				private long groupPairs;
				private long groupsSeen;

				@Override
				public void begin(long key, long predicate, int ignored) {
					if (!coverage.covers(predicate)) {
						encoder = null;
						return;
					}
					this.key = key;
					this.predicate = predicate;
					this.groupPairs = 0;
					encoder = LmdbAdjacencyRunCodec.sizingEncoder(tempContexts);
					boolean outgoing = plane == LmdbReferenceNodeLocator.PLANE_OUTGOING_EXPLICIT
							|| plane == LmdbReferenceNodeLocator.PLANE_OUTGOING_INFERRED;
					if (outgoing && !ValueIds.isReference(key)) {
						throw new IllegalStateException("an outgoing group key must be a reference id: " + key);
					}
				}

				@Override
				public void pair(long neighbor, long context) {
					if (encoder == null) {
						return;
					}
					encoder.accept(neighbor, context);
					groupPairs++;
				}

				@Override
				public void end() {
					if (encoder == null) {
						return;
					}
					LmdbAdjacencyRunCodec.Encoder.Result result = encoder.finish();
					encoder = null;
					runBytes = Math.addExact(runBytes, result.totalBytes);
					groupCount++;
					pairCount = Math.addExact(pairCount, groupPairs);
					switch (plane) {
					case LmdbReferenceNodeLocator.PLANE_OUTGOING_EXPLICIT:
						outgoingExplicitPairs += groupPairs;
						break;
					case LmdbReferenceNodeLocator.PLANE_INCOMING_EXPLICIT:
						incomingExplicitPairs += groupPairs;
						break;
					case LmdbReferenceNodeLocator.PLANE_OUTGOING_INFERRED:
						outgoingInferredPairs += groupPairs;
						break;
					default:
						incomingInferredPairs += groupPairs;
						break;
					}
					if (ValueIds.isReference(key)) {
						workspace.recordGroup(ValueIds.getIdType(key), ValueIds.getValue(key), plane);
					} else {
						long predicateOrdinal = unsignedIndexOf(sortedPredicates, predicate);
						inlineSizing.computeIfAbsent(predicateOrdinal * 4 + plane, k -> new InlinePlaneSizing())
								.addKey(key);
					}
					if (++groupsSeen % SNAPSHOT_CHECK_GROUP_INTERVAL == 0) {
						try {
							scanner.ensureSnapshotValid();
						} catch (IOException e) {
							throw new IllegalStateException("build snapshot invalidated", e);
						}
					}
				}
			};
		}

		long predictedBaseBytes(long predicateCount, long contextCount, int predicateWidth) {
			long total = runBytes;
			total = Math.addExact(total, predicateCount * 8 + contextCount * 8);
			// locator top tables
			for (int t = 0; t < 4; t++) {
				long pages = (workspace.maxActivePayloadExclusive(ValueIds.T_URI + t)
						+ LmdbReferenceNodeLocator.PAGE_SLOTS - 1) >>> LmdbReferenceNodeLocator.PAGE_SHIFT;
				total = Math.addExact(total, pages * 5);
			}
			// pages and headers
			long[] pageState = new long[3]; // currentType, currentPageNo, activeInPage
			long[] headerTotal = new long[1];
			long[] pageTotal = new long[1];
			pageState[0] = -1;
			workspace.forEachActiveNode((type, payload, planeCounts) -> {
				long pageNo = payload >>> LmdbReferenceNodeLocator.PAGE_SHIFT;
				if (type != pageState[0] || pageNo != pageState[1]) {
					if (pageState[0] >= 0) {
						pageTotal[0] += alignUp(640 + 5 * pageState[2], 8);
					}
					pageState[0] = type;
					pageState[1] = pageNo;
					pageState[2] = 0;
				}
				pageState[2]++;
				long groups = planeCounts[0] + planeCounts[1] + planeCounts[2] + planeCounts[3];
				headerTotal[0] += alignUp(4L * predicateWidth + groups * (predicateWidth + 5L), 8);
			});
			if (pageState[0] >= 0) {
				pageTotal[0] += alignUp(640 + 5 * pageState[2], 8);
			}
			total = Math.addExact(total, headerTotal[0]);
			total = Math.addExact(total, pageTotal[0]);
			for (InlinePlaneSizing plane : inlineSizing.values()) {
				total = Math.addExact(total, plane.totalBytes());
			}
			// alignment/region slack allowance: eight bytes per node/group/page allocation upper bound
			total = Math.addExact(total, (workspace.activeNodeCount() + workspace.groupCount()) * 8 + 4096);
			return total;
		}
	}

	/**
	 * Streaming exact sizing of one inline incoming plane, replicating the block partition and layout of
	 * {@link LmdbInlineIncomingIndex}.
	 */
	private static final class InlinePlaneSizing {
		private long keyCount;
		private long blockCount;
		private long blockBytes;
		private long blockFirstKey;
		private int blockKeys;
		private long lastKey;

		void addKey(long key) {
			if (keyCount > 0 && Long.compareUnsigned(lastKey, key) >= 0) {
				throw new IllegalStateException("inline keys must be strictly unsigned ascending within a plane");
			}
			if (keyCount == 0 || blockKeys == LmdbInlineIncomingIndex.MAX_BLOCK_KEYS
					|| (key >>> 48) != (blockFirstKey >>> 48)) {
				closeBlock();
				blockFirstKey = key;
				blockKeys = 0;
			}
			blockKeys++;
			lastKey = key;
			keyCount++;
		}

		private void closeBlock() {
			if (blockKeys == 0) {
				return;
			}
			long maxDelta = lastKey - blockFirstKey;
			int width = 64 - Long.numberOfLeadingZeros(maxDelta);
			long packed = (((long) blockKeys * width + 63) >>> 6) * 8;
			long refsAt = alignUp(16 + packed, 8);
			blockBytes += alignUp(refsAt + 5L * blockKeys, 8);
			blockCount++;
		}

		long totalBytes() {
			closeBlock();
			blockKeys = 0;
			return LmdbInlineIncomingIndex.RADIX_DIRECTORY_BYTES + blockCount * 5 + blockBytes;
		}
	}

	// ------------------------------------------------------------------
	// Pass 3
	// ------------------------------------------------------------------

	private static final class FillState {
		final LmdbAdjacencyCoverage coverage;
		final LmdbAdjacencyContextCatalog contextCatalog;
		final LmdbAdjacencyPredicateCatalog predicateCatalog;
		final LmdbAdjacencyArena baseArena;
		final LmdbReferenceNodeLocator.TwoPhaseBuilder twoPhase;
		final AdjacencySourceScanner scanner;

		long runBytes;
		long groupCount;
		long pairCount;
		final Map<Long, LmdbInlineIncomingIndex> inlinePlanes = new HashMap<>();
		final Map<Long, LongList[]> inlineCollectors = new HashMap<>(); // [keys, refs] per plane key

		FillState(LmdbAdjacencyCoverage coverage, LmdbAdjacencyContextCatalog contextCatalog,
				LmdbAdjacencyPredicateCatalog predicateCatalog, LmdbAdjacencyArena baseArena,
				LmdbReferenceNodeLocator.TwoPhaseBuilder twoPhase, AdjacencySourceScanner scanner) {
			this.coverage = coverage;
			this.contextCatalog = contextCatalog;
			this.predicateCatalog = predicateCatalog;
			this.baseArena = baseArena;
			this.twoPhase = twoPhase;
			this.scanner = scanner;
		}

		void scanAll() throws IOException {
			scanner.scanOutgoing(true, consumer(LmdbReferenceNodeLocator.PLANE_OUTGOING_EXPLICIT));
			scanner.scanIncoming(true, consumer(LmdbReferenceNodeLocator.PLANE_INCOMING_EXPLICIT));
			scanner.scanOutgoing(false, consumer(LmdbReferenceNodeLocator.PLANE_OUTGOING_INFERRED));
			scanner.scanIncoming(false, consumer(LmdbReferenceNodeLocator.PLANE_INCOMING_INFERRED));
			// build every collected inline plane index from its sorted keys and run references
			for (Map.Entry<Long, LongList[]> entry : inlineCollectors.entrySet()) {
				LmdbInlineIncomingIndex index = LmdbInlineIncomingIndex.build(baseArena, entry.getValue()[0].toArray(),
						entry.getValue()[1].toArray());
				if (index != null) {
					inlinePlanes.put(entry.getKey(), index);
				}
			}
		}

		private AdjacencySourceScanner.GroupConsumer consumer(int plane) {
			return new AdjacencySourceScanner.GroupConsumer() {
				private LmdbAdjacencyRunCodec.Encoder encoder;
				private long key;
				private long predicate;
				private long groupPairs;
				private long groupsSeen;

				@Override
				public void begin(long key, long predicate, int ignored) {
					if (!coverage.covers(predicate)) {
						encoder = null;
						return;
					}
					this.key = key;
					this.predicate = predicate;
					this.groupPairs = 0;
					encoder = LmdbAdjacencyRunCodec.writingEncoder(contextCatalog, baseArena);
				}

				@Override
				public void pair(long neighbor, long context) {
					if (encoder == null) {
						return;
					}
					encoder.accept(neighbor, context);
					groupPairs++;
				}

				@Override
				public void end() {
					if (encoder == null) {
						return;
					}
					LmdbAdjacencyRunCodec.Encoder.Result result = encoder.finish();
					encoder = null;
					runBytes = Math.addExact(runBytes, result.totalBytes);
					groupCount++;
					pairCount = Math.addExact(pairCount, groupPairs);
					long predicateOrdinal = predicateCatalog.ordinalForRaw(predicate);
					if (predicateOrdinal < 0) {
						throw new IllegalStateException("covered predicate missing from the dictionary: " + predicate);
					}
					if (ValueIds.isReference(key)) {
						twoPhase.fillEntry(ValueIds.getIdType(key), ValueIds.getValue(key), plane, predicateOrdinal,
								result.rootRef);
					} else {
						LongList[] collector = inlineCollectors.computeIfAbsent(predicateOrdinal * 4 + plane,
								k -> new LongList[] { new LongList(), new LongList() });
						collector[0].add(key);
						collector[1].add(result.rootRef);
					}
					if (++groupsSeen % SNAPSHOT_CHECK_GROUP_INTERVAL == 0) {
						try {
							scanner.ensureSnapshotValid();
						} catch (IOException e) {
							throw new IllegalStateException("build snapshot invalidated", e);
						}
					}
				}
			};
		}
	}

	// ------------------------------------------------------------------
	// helpers
	// ------------------------------------------------------------------

	/**
	 * Pass-1 raw-to-ordinal context lookup over the temporary sorted domain, freed with the build workspace; Pass 3
	 * uses the base catalog copy instead.
	 */
	private static final class TempContextCatalog implements ContextCatalog {
		private final long[] sortedRawIds;

		TempContextCatalog(long[] sortedRawIds) {
			this.sortedRawIds = sortedRawIds;
		}

		@Override
		public long size() {
			return sortedRawIds.length + 1L;
		}

		@Override
		public long ordinalForRaw(long rawContext) {
			if (rawContext == 0) {
				return 0;
			}
			long index = unsignedIndexOf(sortedRawIds, rawContext);
			return index < 0 ? -1 : index + 1;
		}

		@Override
		public long rawForOrdinal(long ordinal) {
			if (ordinal == 0) {
				return 0;
			}
			if (ordinal < 1 || ordinal > sortedRawIds.length) {
				throw new IllegalArgumentException("context ordinal out of range: " + ordinal);
			}
			return sortedRawIds[(int) (ordinal - 1)];
		}
	}

	private static long unsignedIndexOf(long[] sorted, long key) {
		int low = 0;
		int high = sorted.length - 1;
		while (low <= high) {
			int mid = (low + high) >>> 1;
			int cmp = Long.compareUnsigned(sorted[mid], key);
			if (cmp < 0) {
				low = mid + 1;
			} else if (cmp > 0) {
				high = mid - 1;
			} else {
				return mid;
			}
		}
		return -1;
	}

	private static long alignUp(long value, long alignment) {
		return Math.addExact(value, alignment - 1) & -alignment;
	}

	/**
	 * Bounded growable primitive long buffer (build metadata; no boxing).
	 */
	private static final class LongList {
		private long[] values = new long[16];
		private int size;

		void add(long value) {
			if (size == values.length) {
				values = Arrays.copyOf(values, Math.multiplyExact(values.length, 2));
			}
			values[size++] = value;
		}

		long get(int index) {
			return values[index];
		}

		long[] toArray() {
			return Arrays.copyOf(values, size);
		}
	}
}
